import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"UniApp 面试 Q&A(速查版)","description":"面向跨端面试的高频问答,按「基础选型 → 生命周期与路由 → 样式与性能」三段组织。 原理与实战展开见 UniApp 知识体系。","frontmatter":{},"headers":[],"relativePath":"面试/UniApp/index.md","filePath":"面试/UniApp/index.md","lastUpdated":1793113268000}'),d={name:"面试/UniApp/index.md"};function n(o,a,l,p,h,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="uniapp-面试-q-a-速查版" tabindex="-1">UniApp 面试 Q&amp;A(速查版) <a class="header-anchor" href="#uniapp-面试-q-a-速查版" aria-label="Permalink to &quot;UniApp 面试 Q&amp;A(速查版)&quot;">​</a></h1><blockquote><p>面向跨端面试的高频问答,按「基础选型 → 生命周期与路由 → 样式与性能」三段组织。 原理与实战展开见 <a href="/前端/uniapp/">UniApp 知识体系</a>。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-basics">跨端基础与选型</a> — UniApp vs 原生小程序、Taro/RN/Flutter 选型、条件编译、原生能力与支付</li><li><a href="./2-lifecycle-navigation">生命周期、路由与页面栈</a> — onLoad/onShow 区别、跳转方式、页面栈上限 10 层、跨页通信</li><li><a href="./3-style-data-performance">样式、数据绑定与性能</a> — rpx、setData 原理与优化、包体积治理、首屏优化</li></ol><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题目</th><th>一句话答案</th></tr></thead><tbody><tr><td>UniApp vs 原生小程序?</td><td>一套代码多端 vs 平台原生,前者开发成本低,后者性能与生态深度好</td></tr><tr><td>onLoad 和 onShow 的区别?</td><td>onLoad 只触发一次用于初始化,onShow 每次进入都触发用于刷新</td></tr><tr><td>setData 为什么慢?</td><td>逻辑层与视图层分离,数据要序列化 + 传输 + diff,合并与最小化是核心优化</td></tr><tr><td>rpx 是什么?</td><td>750rpx = 屏幕宽度,设计稿数值直接用 rpx 免换算</td></tr><tr><td>条件编译什么时候执行?</td><td>编译期裁剪,不是运行时判断,所以不影响运行时性能</td></tr><tr><td>页面栈上限?</td><td>10 层,长流程要用「单页 + 内部步骤」而不是层层 navigateTo</td></tr></tbody></table><h2 id="📚-延伸阅读" tabindex="-1">📚 延伸阅读 <a class="header-anchor" href="#📚-延伸阅读" aria-label="Permalink to &quot;📚 延伸阅读&quot;">​</a></h2><ul><li><a href="/前端/uniapp/">UniApp 知识体系(17 篇)</a></li><li><a href="/面试/小程序/19-vs_uniapp">原生小程序、uni-app、Taro 有什么区别</a></li><li><a href="/前端/cross-platform/">跨端进阶对比</a></li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>UniApp 的题主要考三块:跨端选型与条件编译、生命周期与页面栈、setData 与性能。</li><li>回答时多用「原理 → 代价 → 解法」三段式,比罗列 API 更能体现深度。</li><li>每题都能落到 <a href="/前端/uniapp/">UniApp 知识体系</a> 的对应篇目,不会答到一半卡住。</li></ul>',10)])])}const f=t(d,[["render",n]]);export{u as __pageData,f as default};
